<script setup>
import { computed, onMounted, ref } from 'vue'
const animals=ref([]), staff=ref([]), records=ref([])
function load(){ animals.value=JSON.parse(localStorage.getItem('zoocare_animals')||'[]'); staff.value=JSON.parse(localStorage.getItem('zoocare_staff')||'[]'); records.value=JSON.parse(localStorage.getItem('zoocare_care_records')||'[]') }
onMounted(load)
const active= computed(()=>animals.value.filter(a=>a.status==='Healthy'||a.status==='Under observation').length)
</script>
